'use strict';
// Keep native form values/events as the source of truth; render choices in the app theme.
(()=>{
 const widgets=new Map();let active=null,serial=0;
 function place(panel,anchor){const r=anchor.getBoundingClientRect(),height=Math.min(300,Math.max(130,panel.scrollHeight||260)),below=innerHeight-r.bottom-12,above=r.top-12,width=Math.min(Math.max(210,r.width),innerWidth-24),down=below>=height||below>=above;panel.dataset.placement=down?'below':'above';panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(r.left,innerWidth-width-12))+'px';panel.style.top=down?r.bottom+5+'px':'auto';panel.style.bottom=down?'auto':Math.max(12,innerHeight-r.top+5)+'px';panel.style.maxHeight=Math.max(100,Math.min(300,down?below:above))+'px';}
 function closeAll(focus=false){active?.close(focus);}
 function labelFor(source){if(source.getAttribute('aria-label'))return source.getAttribute('aria-label');const label=source.labels?.[0]||source.closest('label');if(label){const copy=label.cloneNode(true);copy.querySelectorAll('select,input,button,.app-select,.app-combobox').forEach(n=>n.remove());const text=copy.textContent.trim();if(text)return text;}return source.name||source.id||'Choose an option';}
 class Choice{
  constructor(source,listId=null){this.source=source;this.listId=listId;this.free=Boolean(listId);this.id='app-choice-'+(++serial);this.index=-1;this.query='';this.searchTimer=null;
   widgets.set(source,this);this.wrapper=document.createElement('span');this.wrapper.className=this.free?'app-combobox':'app-select';source.before(this.wrapper);this.wrapper.append(source);
   this.button=document.createElement('button');this.button.type='button';this.button.className=this.free?'app-combobox-toggle':'app-select-button';this.button.setAttribute('aria-haspopup','listbox');this.button.setAttribute('aria-expanded','false');this.button.setAttribute('aria-controls',this.id);this.wrapper.append(this.button);
   if(this.free){source.removeAttribute('list');source.dataset.appList=listId;source.setAttribute('role','combobox');source.setAttribute('aria-autocomplete','list');source.setAttribute('aria-controls',this.id);source.setAttribute('aria-expanded','false');source.addEventListener('input',()=>{if(this.committing)return;this.query=source.value;this.open(false);});source.addEventListener('keydown',e=>this.key(e));}
   else{source.classList.add('app-select-source');source.setAttribute('aria-hidden','true');source.tabIndex=-1;for(const key of ['value','selectedIndex']){const descriptor=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,key);Object.defineProperty(source,key,{configurable:true,get:()=>descriptor.get.call(source),set:value=>{descriptor.set.call(source,value);this.sync();}});}}
   this.popup=document.createElement('div');this.popup.className='app-select-popup';this.popup.hidden=true;this.wrapper.append(this.popup);this.list=document.createElement('div');this.list.id=this.id;this.list.setAttribute('role','listbox');this.list.setAttribute('aria-label',labelFor(source));this.popup.append(this.list);
   this.button.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(active===this)this.close(true);else this.open(true);});this.button.addEventListener('keydown',e=>this.key(e));source.addEventListener('change',()=>this.sync());
   this.list.addEventListener('mousedown',e=>e.preventDefault());this.list.addEventListener('click',e=>{const node=e.target.closest('[data-option-index]');if(!node)return;e.preventDefault();e.stopPropagation();this.choose(Number(node.dataset.optionIndex));});
   this.observer=new MutationObserver(()=>{this.sync();if(active===this)this.render();});this.observer.observe(this.free?document.getElementById(listId):source,{childList:true,subtree:true,attributes:true,characterData:true});this.sync();
  }
  options(){const parent=this.free?document.getElementById(this.listId):this.source;return [...(parent?.querySelectorAll('option')||[])].filter(o=>!o.hidden).map(o=>({value:o.value,label:this.free?(o.label||o.value):(o.label||o.textContent),disabled:o.disabled||o.parentElement?.disabled===true}));}
  sync(){this.button.disabled=this.source.disabled;const name=labelFor(this.source);if(this.free)this.button.setAttribute('aria-label','Show '+name+' options');else{this.button.replaceChildren();const text=document.createElement('span');text.className='app-select-label';text.textContent=this.source.options?.[this.source.selectedIndex]?.label||this.source.options?.[this.source.selectedIndex]?.textContent||'Choose…';this.button.append(text);this.button.setAttribute('aria-label',name+': '+text.textContent);this.button.title=text.textContent;}}
  open(focus){if(this.source.disabled)return;if(active!==this){closeAll();active=this;this.query=this.free&&!focus?this.source.value:'';this.wrapper.setAttribute('data-menu-open','');this.button.setAttribute('aria-expanded','true');if(this.free)this.source.setAttribute('aria-expanded','true');this.popup.hidden=false;}
   this.render();place(this.popup,this.wrapper);this.highlight();if(focus)(this.search||this.free&&this.source||this.button).focus({preventScroll:true});
  }
  render(){const all=this.options();if(!this.free&&all.length>8&&!this.search){this.search=document.createElement('input');this.search.type='search';this.search.className='app-option-search';this.search.placeholder='Find an option…';this.search.setAttribute('aria-label','Search '+labelFor(this.source));this.popup.prepend(this.search);this.search.addEventListener('input',()=>{this.query=this.search.value;this.render();});this.search.addEventListener('keydown',e=>this.key(e));}
   this.visible=all.filter(o=>!this.query||o.label.toLocaleLowerCase().includes(this.query.toLocaleLowerCase())||o.value.toLocaleLowerCase().includes(this.query.toLocaleLowerCase()));this.list.replaceChildren();let selected=-1;
   this.visible.forEach((o,i)=>{const node=document.createElement('button');node.type='button';node.tabIndex=-1;node.className='app-select-option';node.id=this.id+'-'+i;node.dataset.optionIndex=String(i);node.setAttribute('role','option');node.setAttribute('aria-selected',String(o.value===this.source.value));node.disabled=o.disabled;node.textContent=o.label;if(o.value===this.source.value)selected=i;this.list.append(node);});
   if(!this.visible.length){const empty=document.createElement('p');empty.className='app-options-empty';empty.textContent='No matching options';this.list.append(empty);}
   this.index=selected>=0?selected:this.visible.findIndex(o=>!o.disabled);this.highlight();
  }
  highlight(){this.list.querySelectorAll('[role="option"]').forEach((node,i)=>node.classList.toggle('is-focused',i===this.index));const node=this.list.children[this.index];if(node?.id){for(const field of [this.button,this.search,this.free&&this.source].filter(Boolean))field.setAttribute('aria-activedescendant',node.id);const top=node.offsetTop,bottom=top+node.offsetHeight;if(top<this.popup.scrollTop)this.popup.scrollTop=top;else if(bottom>this.popup.scrollTop+this.popup.clientHeight)this.popup.scrollTop=Math.max(0,bottom-this.popup.clientHeight);}}
  key(e){if(e.isComposing||e.ctrlKey||e.metaKey||e.altKey)return;const open=active===this;
   if(e.key==='Escape'&&open){e.preventDefault();e.stopImmediatePropagation();this.close(true);return;}
   if(e.key==='Tab'){if(open)this.close();return;}
   if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&(!this.free||open||e.key.startsWith('Arrow'))){e.preventDefault();e.stopPropagation();if(!open){this.open(this.free);return;}let next=this.index,step=e.key==='ArrowUp'?-1:1;if(e.key==='Home')next=-1;if(e.key==='End'){next=this.visible.length;step=-1;}for(let count=0;count<this.visible.length;count++){next=(next+step+this.visible.length)%this.visible.length;if(!this.visible[next].disabled){this.index=next;break;}}this.highlight();return;}
   if(e.key==='Enter'&&open&&this.free&&!this.visible.length){this.close();return;}
   if((e.key==='Enter'||e.key===' '&&!this.free&&e.target===this.button)&&open){e.preventDefault();e.stopPropagation();this.choose(this.index);return;}
   if(!open&&!this.free&&(e.key==='Enter'||e.key===' ')){e.preventDefault();this.open(true);return;}
   if(e.target===this.button&&e.key.length===1&&!this.free){e.preventDefault();if(!open)this.open(false);this.query+=e.key;clearTimeout(this.searchTimer);this.searchTimer=setTimeout(()=>{this.query='';},600);if(this.search)this.search.value=this.query;this.render();}
  }
  choose(index){const option=this.visible[index];if(!option||option.disabled)return;const source=this.source,id=source.id;source.value=option.value;this.sync();this.close();this.committing=true;try{source.dispatchEvent(new Event('input',{bubbles:true}));source.dispatchEvent(new Event('change',{bubbles:true}));}finally{this.committing=false;}queueMicrotask(()=>{const latest=id?document.getElementById(id):source;if(latest?.isConnected){const widget=widgets.get(latest);(widget?.free?latest:widget?.button||latest).focus({preventScroll:true});}});}
  close(focus=false){this.popup.hidden=true;this.wrapper.removeAttribute('data-menu-open');this.button.setAttribute('aria-expanded','false');this.button.removeAttribute('aria-activedescendant');if(this.free){this.source.setAttribute('aria-expanded','false');this.source.removeAttribute('aria-activedescendant');}if(active===this)active=null;this.query='';if(this.search)this.search.value='';if(focus&&this.source.isConnected)(this.free?this.source:this.button).focus({preventScroll:true});}
 }
 function enhance(root=document){for(const node of [...(root.matches?.('select,input[list]')?[root]:[]),...root.querySelectorAll?.('select,input[list]')||[]]){if(widgets.has(node)||node.multiple)continue;if(node.tagName==='SELECT')new Choice(node);else if(document.getElementById(node.getAttribute('list')))new Choice(node,node.getAttribute('list'));}}
 document.addEventListener('click',e=>{if(active&&!active.wrapper.contains(e.target))active.close();},true);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&active){e.preventDefault();e.stopImmediatePropagation();active.close(true);}},true);
 document.addEventListener('toggle',e=>{if(e.target.tagName==='DETAILS'&&!e.target.open&&active&&e.target.contains(active.wrapper))active.close();},true);
 document.addEventListener('close',()=>closeAll(),true);window.addEventListener('atlas-view-before-render',()=>closeAll());window.addEventListener('resize',()=>closeAll());
 document.addEventListener('scroll',e=>{if(active&&!active.popup.contains(e.target))closeAll();},true);
 new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node.nodeType===1)enhance(node);for(const [source,widget]of widgets)if(!source.isConnected){widget.observer.disconnect();if(active===widget)widget.close();widgets.delete(source);}}).observe(document.body,{childList:true,subtree:true});
 window.YCAtlasDropdowns=Object.freeze({enhance,closeAll,place});enhance();
})();
